/** Deterministic text built from the published figures. Not generated by a model, and labelled so wherever it is shown. */
import type { Row } from './screen.ts';
import { isLender } from './screen.ts';
import { isNum, dayWord, pct } from './fmt.ts';

/** Share of liquid names above their own 50-day average, measured rows only. */
export function breadth(rows: readonly Row[]): { pct: number | null; n: number } {
  let up = 0, n = 0;
  for (const r of rows) if (r.liquid && isNum(r.price) && isNum(r.sma50)) { n++; if (r.price > r.sma50) up++; }
  return { pct: n ? (up / n) * 100 : null, n };
}
/** A review checklist for one name, built only from what the feed holds. Each item says what to check and why it came up. */
export function checklistFor(r: Row, today: string): string[] {
  const out: string[] = [];
  out.push('Write what would make you wrong, as a price or an event, before anything else.');
  if (r.next_earnings) out.push(`Results are expected around ${dayWord(r.next_earnings)} (an estimate). Decide before then whether you hold through them.`);
  if (isNum(r.from_high) && r.from_high <= -20) out.push(`It closed ${pct(r.from_high)} from its 52-week high. Find out what changed since, from the company's own filings.`);
  if (isNum(r.rsi) && r.rsi >= 70) out.push(`RSI is ${r.rsi.toFixed(0)}: recent closes were strongly one-sided. Check you are not reacting to a move already made.`);
  if (isNum(r.rsi) && r.rsi <= 30) out.push(`RSI is ${r.rsi.toFixed(0)}: recent closes were strongly one-sided downward. Check the cause is not something that is still happening.`);
  if (isNum(r.vol_spike) && r.vol_spike >= 2) out.push(`Volume was ${r.vol_spike.toFixed(1)}x its recent average. Look for an announcement on that day.`);
  if (!isLender(r) && isNum(r.de) && r.de >= 1) out.push(`Debt to equity is ${r.de.toFixed(2)}. Read how the borrowings are repaid in the latest annual report.`);
  if (isNum(r.pe) && r.pe >= 40) out.push(`PE is ${r.pe.toFixed(0)}: the price already assumes strong growth. Write the growth you assume and check it against the last 3 years.`);
  if (r.risk_lvl === 'HIGH') out.push('The screen grades its risk HIGH. Open the countercase and read each flag before you size anything.');
  if (!r.has_stmts) out.push('No financial statements are held for this name. Treat every ratio as missing, not as zero.');
  out.push(`Set a review date. Data used here is through ${dayWord(r.last_date)}; today is ${dayWord(today)}.`);
  return out;
}
